<template>
  <section><div class="page-head"><div><span class="eyebrow">Live and local</span><h1 class="page-title">Radio</h1><p class="muted">Explore community radio stations from Radio-Browser.info.</p></div><button class="button-secondary" @click="$emit('navigate','addon/radio_browser')">Radio-Browser.info add-on</button></div>
    <div class="row"><input class="input search" placeholder="Search stations…" :value="state.radioSearch" @keydown.enter="$emit('action',{action:'search-radio',payload:$event.target.value})"><button class="button" @click="$emit('action',{action:'search-radio',payload:state.radioSearch})">Search</button><button class="button-secondary" @click="$emit('action',{action:'category',payload:''})">Trending</button><button class="button-secondary" @click="$emit('action',{action:'category',payload:'jazz'})">Jazz</button><button class="button-secondary" @click="$emit('action',{action:'category',payload:'rock'})">Rock</button></div>
    <div class="tabs"><button v-for="tab in ['Trending','Favorites','Add Station','Report Radio Station','My Profile','Sign In','Exit']" :key="tab" :class="{active:state.radioPage===tab}" @click="state.radioPage=tab;tab==='My Profile'||tab==='Sign In'?$emit('action',{action:'signin-radio'}):tab==='Exit'?$emit('action',{action:'exit-radio'}):tab==='Add Station'?$emit('action',{action:'add-station'}):tab==='Report Radio Station'?$emit('action',{action:'report'}):null">{{tab}}</button></div>
    <div v-if="state.radioLoading" class="empty">Finding stations…</div><div v-else-if="state.radioError" class="empty">{{state.radioError}}<br><button class="quiet" @click="$emit('action',{action:'search-radio',payload:state.radioSearch})">Try again</button></div>
    <div v-else-if="state.stations.length" class="station-list"><article v-for="station in state.stations" :key="station.stationuuid" class="station"><img :src="station.favicon||'https://radio-browser.info/favicon.ico'" alt="" @error="$event.target.src='https://radio-browser.info/favicon.ico'"><div class="grow"><strong>{{station.name}}</strong><small>{{station.country||'Worldwide'}} · {{station.tags||'Radio'}}</small></div><audio controls preload="none" :src="station.url_resolved" :aria-label="'Play '+station.name"></audio></article></div><div v-else class="empty">No stations to show. Try a search or check your connection.</div>
    <p class="footer">Station information and streams are provided by the Radio-Browser community. Stream availability may vary.</p>
  </section>
</template>
